    var params: [String: Any] = [:]
    if let id = workspaceID ?? currentWorkspaceID {
        params["workspace_id"] = id
    }
    send(method: "surface.list", params: params) { [weak self] result in
        if let list = result["surfaces"] as? [[String: Any]] {
