func (r *Resolver) Render(resumeBinding map[string]any, maxMessages int) (text string, supported bool, sessionID string, err error) {
	if resumeBinding == nil {
		return "", false, "", nil
	}
	kind, _ := resumeBinding["kind"].(string)
	if kind != "claude" {
		return "", false, "", nil
	}

	projectDir, err := r.resolveProjectDir(resumeBinding)
	if err != nil {
		return "", true, "", err
	}
	if projectDir == "" {
		// Claude surface but no transcript directory yet.
		return "", true, "", nil
	}

	transcriptPath, err := latestJSONL(projectDir)
	if err != nil {
		return "", true, "", err
	}
	if transcriptPath == "" {
		return "", true, "", nil
	}

	sessionID = strings.TrimSuffix(filepath.Base(transcriptPath), ".jsonl")

	info, err := os.Stat(transcriptPath)
	if err != nil {
		return "", true, sessionID, err
	}

